"""Write data/manifest.yaml: every source and every generated file with sha256."""

from __future__ import annotations

from pathlib import Path

import yaml

from arthai_gen import config
from arthai_gen.util import sha256_file

SOURCES = [
    {
        "name": "Synthea",
        "version": config.SYNTHEA_TAG,
        "license": "Apache-2.0",
        "url": "https://github.com/synthetichealth/synthea/releases/download/v4.0.0/"
        "synthea-with-dependencies.jar",
        "sha256": config.SYNTHEA_JAR_SHA256,
        "used": "birth date, sex, encounter date and class",
    },
    {
        "name": "Eclipse Temurin JDK",
        "version": config.JDK_VERSION,
        "license": "GPL-2.0 WITH Classpath-exception-2.0",
        "sha256": config.JDK_SHA256,
        "used": "runs Synthea only; not redistributed",
    },
    {
        "name": "CMS HCPCS Level II, October 2026 alpha-numeric file",
        "license": "public (CMS)",
        "url": "https://www.cms.gov/files/zip/october-2026-alpha-numeric-hcpcs-file.zip",
        "sha256": "08c2202fa92c1d1fb6f31b808b61c767bc487954f6930b6a0f8d09c89af5992f",
        "used": "data/reference/codes/hcpcs_l2_subset.csv",
    },
    {
        "name": "ICD-10-CM FY2027 code descriptions (CDC/NCHS via CMS)",
        "license": "free use with attribution; titles unchanged",
        "url": "https://www.cms.gov/files/zip/2027-code-descriptions-tabular-order.zip",
        "sha256": "91c6c9d1117764ce72375a0f3a5493b1725dafbc1ab283b55799076c9e194965",
        "used": "data/reference/codes/icd10cm_fy2027_subset.csv",
    },
    {
        "name": "X12 CARC and RARC code lists (values only)",
        "license": "X12 copyright; no text stored",
        "url": "https://x12.org/codes/claim-adjustment-reason-codes",
        "checked": "2026-10-28",
        "used": "data/reference/codes/carc.csv, rarc.csv",
    },
]


def write(seed: int, synthea_seed: int, out: Path = config.DATA / "manifest.yaml") -> None:
    files = sorted(
        p
        for base in (config.SYNTH, config.REF_CODES, config.SCHEMAS)
        for p in base.rglob("*")
        if p.is_file()
    )
    generated = []
    for p in files:
        entry: dict[str, object] = {
            "path": p.relative_to(config.ROOT).as_posix(),
            "sha256": sha256_file(p),
        }
        if p.suffix == ".jsonl":
            entry["rows"] = len(p.read_text(encoding="utf-8").splitlines())
        generated.append(entry)
    doc = {
        "generator_version": config.GENERATOR_VERSION,
        "demo_today": config.DEMO_TODAY.isoformat(),
        "seed": seed,
        "synthea": {
            "seed": synthea_seed,
            "clinician_seed": synthea_seed,
            "population": config.SYNTHEA_POPULATION,
            "reference_date": "20261028",
            "thread_pool_size": 1,
            "network": "none (unshare -rn)",
        },
        "sources": SOURCES,
        "files": generated,
    }
    header = "# Generated by `make data`. Do not edit by hand.\n"
    out.write_text(
        header + yaml.safe_dump(doc, sort_keys=True, width=100), encoding="utf-8", newline="\n"
    )
